using System.Security.Cryptography; using System.Text.Json; using Microsoft.CodeAnalysis; using Microsoft.CodeAnalysis.CSharp; using Microsoft.CodeAnalysis.CSharp.Syntax;
var argsMap=Enumerable.Range(0,args.Length/2).ToDictionary(i=>args[i*2],i=>args[i*2+1]); var root=Path.GetFullPath(argsMap["--source-root"]); var projectId=argsMap["--project-id"]; var facts=new List<object>();
foreach(var file in Directory.EnumerateFiles(root,"*.cs",SearchOption.AllDirectories)){var text=File.ReadAllText(file);var tree=CSharpSyntaxTree.ParseText(text);var model=CSharpCompilation.Create("semantic",new[]{tree}).GetSemanticModel(tree);var hash=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(file))).ToLowerInvariant();var relative=Path.GetRelativePath(root,file).Replace('\\','/');foreach(var type in tree.GetRoot().DescendantNodes().OfType<TypeDeclarationSyntax>()){var e=Evidence(type.GetLocation()); facts.Add(new {kind="type",name=type.Identifier.Text,project_id=projectId,evidence=e,properties=new {base_type=type.BaseList?.Types.FirstOrDefault()?.Type.ToString(),interfaces=type.BaseList?.Types.Skip(1).Select(x=>x.Type.ToString()),type_kind=type.Kind().ToString()}});var controller=type.Identifier.Text.EndsWith("Controller")||type.AttributeLists.ToString().Contains("Controller");foreach(var method in type.Members.OfType<MethodDeclarationSyntax>()){var me=Evidence(method.GetLocation());facts.Add(new {kind=controller?"action":"method",name=method.Identifier.Text,project_id=projectId,evidence=me,properties=new {owner=type.Identifier.Text,return_type=method.ReturnType.ToString(),parameters=method.ParameterList.Parameters.Select(p=>new {name=p.Identifier.Text,type=p.Type?.ToString()})}});foreach(var attribute in method.AttributeLists.SelectMany(a=>a.Attributes).Concat(type.AttributeLists.SelectMany(a=>a.Attributes))){var name=attribute.Name.ToString();if(name.Contains("Authorize"))facts.Add(new {kind="authorization_policy",name,project_id=projectId,evidence=me,properties=new {owner=method.Identifier.Text}});if(new[]{"HttpGet","HttpPost","HttpPut","HttpDelete","HttpPatch","Route"}.Any(x=>name.Contains(x)))facts.Add(new {kind="endpoint",name,project_id=projectId,evidence=me,properties=new {owner=method.Identifier.Text,template=attribute.ArgumentList?.Arguments.FirstOrDefault()?.Expression.ToString()});}}}}
object Evidence(Location l){var s=l.GetLineSpan();return new {project_id=projectId,source_path=relative,line_start=s.StartLinePosition.Line+1,line_end=s.EndLinePosition.Line+1,source_hash=hash,extraction_method="roslyn",confidence=1.0,resolution_status="proven",diagnostic=(string?)null};} }
File.WriteAllText(argsMap["--output"],JsonSerializer.Serialize(new {project_id=projectId,facts,warnings=Array.Empty<object>()},new JsonSerializerOptions{WriteIndented=true}));
